-- ── 0003_coach.sql ──
-- AI coach, mock interviews and learning plans

CREATE TABLE IF NOT EXISTS coach_messages (
  id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id    TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  role       TEXT NOT NULL,              -- user | coach
  content    TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_coach_user ON coach_messages(user_id, id);

CREATE TABLE IF NOT EXISTS interviews (
  id          TEXT PRIMARY KEY,
  user_id     TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  role        TEXT NOT NULL,
  kind        TEXT NOT NULL DEFAULT 'mixed',   -- behavioural | technical | mixed
  questions   TEXT NOT NULL,                   -- JSON [{q, focus, tip}]
  answers     TEXT NOT NULL DEFAULT '[]',      -- JSON [{answer, score, verdict, strengths, improve, better}]
  score       INTEGER,
  created_at  TEXT NOT NULL DEFAULT (datetime('now')),
  finished_at TEXT
);
CREATE INDEX IF NOT EXISTS idx_interviews_user ON interviews(user_id, created_at);

CREATE TABLE IF NOT EXISTS plans (
  id          TEXT PRIMARY KEY,
  user_id     TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  role        TEXT NOT NULL,
  content     TEXT NOT NULL,                   -- JSON {summary, weeks:[{week, theme, tasks:[{title, kind, resource, minutes, done}]}]}
  created_at  TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_plans_user ON plans(user_id, created_at);


DO $$ DECLARE r record; BEGIN -- identity columns continue after explicitly inserted ids
  FOR r IN SELECT table_name FROM information_schema.columns WHERE table_schema='public' AND column_name='id' AND is_identity='YES' LOOP
    EXECUTE format('SELECT setval(pg_get_serial_sequence(%L,''id''), COALESCE((SELECT MAX(id) FROM %I),0)+1, false)', r.table_name, r.table_name);
  END LOOP; END $$;

-- ── 0004_recruiters_linkedin.sql ──
-- Recruiters, talent search, LinkedIn sign-in

ALTER TABLE users ADD COLUMN IF NOT EXISTS share_profile INTEGER NOT NULL DEFAULT 0;   -- student opted in to recruiter search
ALTER TABLE users ADD COLUMN IF NOT EXISTS company TEXT;                                -- recruiter's company
ALTER TABLE users ADD COLUMN IF NOT EXISTS must_change_password INTEGER NOT NULL DEFAULT 0;
ALTER TABLE users ADD COLUMN IF NOT EXISTS linkedin_sub TEXT;                           -- LinkedIn OpenID subject
ALTER TABLE users ADD COLUMN IF NOT EXISTS avatar_url TEXT;

CREATE TABLE IF NOT EXISTS shortlist (
  recruiter_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  student_id   TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  stage        TEXT NOT NULL DEFAULT 'shortlisted',   -- shortlisted | contacted | interviewing | offered | passed
  note         TEXT,
  role         TEXT,                                  -- role they are being considered for
  created_at   TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at   TEXT NOT NULL DEFAULT (datetime('now')),
  PRIMARY KEY (recruiter_id, student_id)
);

CREATE TABLE IF NOT EXISTS profile_views (
  id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  recruiter_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  student_id   TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  created_at   TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_views_student ON profile_views(student_id, created_at);
CREATE UNIQUE INDEX IF NOT EXISTS idx_users_linkedin ON users(linkedin_sub);


DO $$ DECLARE r record; BEGIN -- identity columns continue after explicitly inserted ids
  FOR r IN SELECT table_name FROM information_schema.columns WHERE table_schema='public' AND column_name='id' AND is_identity='YES' LOOP
    EXECUTE format('SELECT setval(pg_get_serial_sequence(%L,''id''), COALESCE((SELECT MAX(id) FROM %I),0)+1, false)', r.table_name, r.table_name);
  END LOOP; END $$;

-- ── 0005_university_org.sql ──
-- Multi-level university management:
--   platform admin  → universities
--   university admin → faculties
--   faculty admin    → degree programmes
--   coordinator      → PLOs, subjects, CLOs, skill mapping for their programmes

ALTER TABLE institutions ADD COLUMN IF NOT EXISTS email_domain TEXT;          -- e.g. student.utem.edu.my, used to suggest a university
ALTER TABLE institutions ADD COLUMN IF NOT EXISTS active INTEGER NOT NULL DEFAULT 1;
ALTER TABLE faculties ADD COLUMN IF NOT EXISTS active INTEGER NOT NULL DEFAULT 1;
ALTER TABLE programmes ADD COLUMN IF NOT EXISTS active INTEGER NOT NULL DEFAULT 1;
ALTER TABLE programmes ADD COLUMN IF NOT EXISTS mqa_code TEXT;               -- MQA accreditation reference
ALTER TABLE programmes ADD COLUMN IF NOT EXISTS duration_years INTEGER DEFAULT 4;
ALTER TABLE subjects ADD COLUMN IF NOT EXISTS credits INTEGER;
ALTER TABLE subjects ADD COLUMN IF NOT EXISTS semester INTEGER;
ALTER TABLE subjects ADD COLUMN IF NOT EXISTS updated_at TEXT;

CREATE TABLE IF NOT EXISTS role_assignments (
  id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id        TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  role           TEXT NOT NULL,                 -- uni_admin | faculty_admin | coordinator
  institution_id INTEGER REFERENCES institutions(id) ON DELETE CASCADE,
  faculty_id     INTEGER REFERENCES faculties(id) ON DELETE CASCADE,
  programme_id   INTEGER REFERENCES programmes(id) ON DELETE CASCADE,
  created_by     TEXT,
  created_at     TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_roles_user ON role_assignments(user_id);
CREATE UNIQUE INDEX IF NOT EXISTS idx_roles_unique ON role_assignments(user_id, role, COALESCE(institution_id,0), COALESCE(faculty_id,0), COALESCE(programme_id,0));

-- Every curriculum change is recorded for accreditation audits
CREATE TABLE IF NOT EXISTS curriculum_log (
  id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id      TEXT,
  programme_id INTEGER,
  faculty_id   INTEGER,
  institution_id INTEGER,
  action       TEXT NOT NULL,
  detail       TEXT,
  created_at   TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_curlog ON curriculum_log(institution_id, created_at);

UPDATE institutions SET email_domain='utem.edu.my' WHERE id=1;

-- Real UTeM structure (source: ftmk.utem.edu.my, utem.edu.my/academic)
UPDATE faculties SET short_name='FTMK', name='Fakulti Teknologi Maklumat dan Komunikasi' WHERE id=1;
INSERT INTO faculties (institution_id,name,short_name) VALUES
  (1,'Fakulti Kecerdasan Buatan dan Keselamatan Siber','FAIX'),
  (1,'Fakulti Teknologi dan Kejuruteraan Elektronik dan Komputer','FTKEK'),
  (1,'Fakulti Teknologi dan Kejuruteraan Elektrik','FTKE'),
